      "output": "```javascript\nfunction mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}\n\nfunction init(seed){\n  var rng=mulberry32(seed);\n  var ships=[];\n  for(var i=0;i<3;i++) ships.push({state:'waiting',vessels:2+Math.floor(rng()*3)});\n  return{rng:rng,ships:ships,yard:120,t:0,throughput:0,speed:25,berths:[0,0,0]};\n}\n\nfunction step(s){\n  var r=s.rng,per=2/3600;\n  var occupied=s.berths[0]+s.berths[1]+s.berths[2];\n  for(var i=0;i<4;i++) if(s.berths[i%3]===0&&s.ships[0].state==='waiting'){s.ships[0].state='working';s.berths[i%3]=1;break}\n  for(var i=0;i<3;i++) if(s.ships[i].state==='working'){var q=Math.min(Math.floor(r()*4)+1,s.ships[i].vessels);s.ships[i].vessels-=q;s.throughput+=q;if(s.ships[i].vessels<=0){s.ships[i].state='departed';s.berths[i]=0}}\n  for(var i=0;i<3;i++) if(s.ships[i].state==='departed') s.ships[i]={state:'waiting',vessels:2+Math.floor(r()*3)};\n  s.yard=Math.max(0,Math.min(300,s.yard+Math.floor(r()*7)-3));\n  s.t+=2;\n  return{berthOcc:occupied/3,craneQ:s.throughput,yardOcc:s.yard/300,waiting:s.ships.filter(function(x){return x.state==='waiting'}).length,throughput:s.throughput};\n}\n```\n\n**指标定义：**\n\n| 指标 | 公式 | 说明 |\n|---|---|---|\n| 泊位占用率 | 占用泊位数 / 3 | 值域 [0, 1] |\n| 岸桥作业量 | 当天累计吞吐（自然箱） | 单调递增 |\n| 堆场占用率 | yard / 300 | 值域 [0, 1]，yard 硬钳制在 [0, 300] |\n| 等待船数 | state === 'waiting' 的船数 | 值域 [0, 3] |\n| 当天累计吞吐 | 所有已卸/装自然箱之和 | 单调递增 |\n\n**堆场增减规则：** 每 tick 变化量为 `floor(rng()*7) - 3`，即均匀分布在 {-3, -2, -1, 0, 1, 2, 3}，均值 0，长期在容量附近波动。硬上限 300 保证占用率 ≤ 100%。"
